sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var requestBody = request.body.data;
    var eventName = requestBody.eventName;
    var eventDate = requestBody.eventDate;
    var location = requestBody.location;
    var contactPerson = requestBody.contactPerson;

    if (!eventName || !eventDate || !location || !contactPerson) {
        response.setStatus(400);
        return response.setBody({ error: "Missing required fields" });
    }

    var _eventRecordGR = new GlideRecordSecure('x_1610434_event_0_event_record');
    _eventRecordGR.initialize();
    _eventRecordGR.setValue('event_name', eventName);
    _eventRecordGR.setValue('event_date', eventDate);
    _eventRecordGR.setValue('location', location);
    _eventRecordGR.setValue('contact_person', contactPerson);
    _eventRecordGR.insert();

    response.setStatus(201);
    return response.setBody({
        message: "Event created successfully",
        eventId: _eventRecordGR.getUniqueValue()
    });

})(request, response);
